#define NPY_NO_DEPRECATED_API NPY_1_7_API_VERSION
#include <Python.h>
#include <numpy/arrayobject.h>
#include <math.h>

/* Helper to convert any object to a contiguous double array */
static PyArrayObject *as_double_array(PyObject *obj, int ndim) {
    PyArrayObject *arr = (PyArrayObject *)PyArray_FROMANY(
        obj,
        NPY_DOUBLE,
        ndim,
        ndim,
        NPY_ARRAY_C_CONTIGUOUS | NPY_ARRAY_ALIGNED);
    if (!arr) {
        PyErr_SetString(PyExc_TypeError, "Failed to convert input to double array");
    }
    return arr;
}

/* Compute portfolio variance given weights and covariance matrix */
static PyObject *portfolio_variance(PyObject *self, PyObject *args) {
    PyObject *weights_obj, *cov_obj;
    if (!PyArg_ParseTuple(args, "OO", &weights_obj, &cov_obj))
        return NULL;

    PyArrayObject *weights = as_double_array(weights_obj, 1);
    PyArrayObject *cov = as_double_array(cov_obj, 2);
    if (!weights || !cov) {
        Py_XDECREF(weights);
        Py_XDECREF(cov);
        return NULL;
    }

    npy_intp n = PyArray_DIM(weights, 0);
    if (PyArray_DIM(cov, 0) != n || PyArray_DIM(cov, 1) != n) {
        PyErr_SetString(PyExc_ValueError, "Dimensions of weights and covariance matrix do not match");
        Py_DECREF(weights);
        Py_DECREF(cov);
        return NULL;
    }

    double *w = (double *)PyArray_DATA(weights);
    double *c = (double *)PyArray_DATA(cov);

    double var = 0.0;
    for (npy_intp i = 0; i < n; ++i) {
        for (npy_intp j = 0; j < n; ++j) {
            var += w[i] * c[i * n + j] * w[j];
        }
    }

    Py_DECREF(weights);
    Py_DECREF(cov);
    return Py_BuildValue("d", var);
}

/* Module method table */
static PyMethodDef PortfolioMethods[] = {
    {"variance", portfolio_variance, METH_VARARGS, "Calculate portfolio variance"},
    {NULL, NULL, 0, NULL}
};

/* Module definition */
static struct PyModuleDef portfoliomodule = {
    PyModuleDef_HEAD_INIT,
    "portfolio_optimized",
    "Optimized portfolio calculations using NumPy",
    -1,
    PortfolioMethods
};

/* Module initialization */
PyMODINIT_FUNC PyInit_portfolio_optimized(void) {
    import_array();  // Initialize NumPy C-API
    return PyModule_Create(&portfoliomodule);
}
EOF"
}
