{"choice": "shell_command", "command": "cat > portfolio_optimized.c <<'EOF'
/* C extension implementing fast portfolio risk and return calculations. */

#include <stddef.h>
#include <math.h>

/**
 * Compute portfolio risk = sqrt(w.T @ cov @ w).
 *
 * Parameters
 * ----------
 * weights    : pointer to a 1‑D array of length n (portfolio weights)
 * cov_matrix : pointer to a flattened n×n row‑major covariance matrix
 * n          : number of assets
 *
 * Returns
 * -------
 * risk value as double
 */

double portfolio_risk(const double *weights, const double *cov_matrix, size_t n) {
    double sum = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double wi = weights[i];
        for (size_t j = 0; j < n; ++j) {
            double wj = weights[j];
            double cov = cov_matrix[i * n + j];
            sum += wi * wj * cov;
        }
    }
    return sqrt(sum);
}

/**
 * Compute portfolio expected return = w.T @ mu.
 *
 * Parameters
 * ----------
 * weights : pointer to a 1‑D array of length n (portfolio weights)
 * mu      : pointer to a 1‑D array of length n (expected returns)
 * n       : number of assets
 *
 * Returns
 * -------
 * expected return as double
 */

double portfolio_return(const double *weights, const double *mu, size_t n) {
    double ret = 0.0;
    for (size_t i = 0; i < n; ++i) {
        ret += weights[i] * mu[i];
    }
    return ret;
}

/**
 * Compute Sharpe ratio = (return - risk_free_rate) / risk.
 */

double sharpe_ratio(const double *weights, const double *mu, const double *cov_matrix,
                    size_t n, double risk_free_rate) {
    double ret = portfolio_return(weights, mu, n);
    double risk = portfolio_risk(weights, cov_matrix, n);
    if (risk == 0.0) return 0.0;
    return (ret - risk_free_rate) / risk;
}

