#include <stddef.h>
#include <math.h>

/**
 * Compute portfolio risk = sqrt(w^T @ cov @ w).
 *
 * Parameters
 * ----------
 * weights    : pointer to a 1‑D array of length n (portfolio weights)
 * cov_matrix : pointer to a flattened n×n row‑major covariance matrix
 * n          : number of assets
 *
 * Returns
 * -------
 * The portfolio standard deviation (risk). If n is zero, returns 0.0.
 */
static double portfolio_risk(const double *weights, const double *cov_matrix, size_t n) {
    if (n == 0) return 0.0;
    double variance = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double wi = weights[i];
        for (size_t j = 0; j < n; ++j) {
            double wj = weights[j];
            double cov_ij = cov_matrix[i * n + j];
            variance += wi * wj * cov_ij;
        }
    }
    return sqrt(variance);
}

/**
 * Compute portfolio expected return = w^T @ returns.
 *
 * Parameters
 * ----------
 * weights   : pointer to a 1‑D array of length n (portfolio weights)
 * returns   : pointer to a 1‑D array of length n (expected returns per asset)
 * n         : number of assets
 *
 * Returns
 * -------
 * The portfolio expected return. If n is zero, returns 0.0.
 */
static double portfolio_return(const double *weights, const double *returns, size_t n) {
    if (n == 0) return 0.0;
    double exp_ret = 0.0;
    for (size_t i = 0; i < n; ++i) {
        exp_ret += weights[i] * returns[i];
    }
    return exp_ret;
}

/**
 * Public API: compute both risk and return.
 *
 * Parameters
 * ----------
 * weights      : pointer to a 1‑D array of length n (portfolio weights)
 * cov_matrix   : pointer to a flattened n×n row‑major covariance matrix
 * returns_vec  : pointer to a 1‑D array of length n (expected returns per asset)
 * n            : number of assets
 * out_risk     : pointer to double where risk will be stored
 * out_return   : pointer to double where return will be stored
 */
void portfolio_metrics(const double *weights,
                       const double *cov_matrix,
                       const double *returns_vec,
                       size_t n,
                       double *out_risk,
                       double *out_return) {
    if (!out_risk || !out_return) return;
    *out_risk = portfolio_risk(weights, cov_matrix, n);
    *out_return = portfolio_return(weights, returns_vec, n);
}

