from pathlib import Path
import pandas as pd

# Paths to source data directories
SOURCE_A = Path('/data/source_a/users.json')
SOURCE_B = Path('/data/source_b/users.csv')
SOURCE_C = Path('/data/source_c/users.parquet')

# Output locations
MERGED_PARQUET = Path('/app/merged_users.parquet')
CONFLICTS_JSON = Path('/app/conflicts.json')

def load_json(path: Path) -> pd.DataFrame:
    if not path.is_file():
        return pd.DataFrame()
    with open(path, 'r', encoding='utf-8') as f:
        data = json.load(f)
    return pd.json_normalize(data)

def load_csv(path: Path) -> pd.DataFrame:
    if not path.is_file():
        return pd.DataFrame()
    return pd.read_csv(path)

def load_parquet(path: Path) -> pd.DataFrame:
    if not path.is_file():
        return pd.DataFrame()
    return pd.read_parquet(path)

def merge_dataframes(dfs):
    # Concatenate all dataframes
    combined = pd.concat(dfs, ignore_index=True)
    # Identify duplicate user IDs (assuming 'id' column exists)
    if 'id' in combined.columns:
        duplicates = combined[combined.duplicated(subset=['id'], keep=False)]
        # Keep the first occurrence of each duplicate
        merged = combined.drop_duplicates(subset=['id'], keep='first')
    else:
        duplicates = pd.DataFrame()
        merged = combined
    return merged, duplicates

def main():
    df_a = load_json(SOURCE_A)
    df_b = load_csv(SOURCE_B)
    df_c = load_parquet(SOURCE_C)

    merged_df, conflicts_df = merge_dataframes([df_a, df_b, df_c])

    # Ensure output directory exists
    MERGED_PARQUET.parent.mkdir(parents=True, exist_ok=True)
    CONFLICTS_JSON.parent.mkdir(parents=True, exist_ok=True)

    # Write merged data to Parquet
    merged_df.to_parquet(MERGED_PARQUET, index=False)

    # Write conflicts to JSON
    if not conflicts_df.empty:
        conflicts_json = conflicts_df.to_dict(orient='records')
        with open(CONFLICTS_JSON, 'w', encoding='utf-8') as f:
            json.dump(conflicts_json, f, indent=2)
    else:
        # Write empty list if no conflicts
        with open(CONFLICTS_JSON, 'w', encoding='utf-8') as f:
            json.dump([], f)

if __name__ == '__main__':
    main()
PY"}}
